// Compare the computed HMAC against the header, then dedupe.
// Plain string work only — no Node built-ins, so nothing here hits the sandbox.

const item = $input.first();

// The signature the agent sent.
const headers = $('Webhook: agent-action').first().json.headers || {};
const sent = String(headers['x-agent-signature'] || '');

// What the Crypto node computed over the RAW body.
const computed = String(item.json.computed_hmac || '');

// Constant-time-ish comparison. crypto.timingSafeEqual is unavailable in this sandbox,
// so this loops over every character rather than short-circuiting on first mismatch.
// Length is compared separately, which does leak length — acceptable here because the
// length of a hex SHA-256 digest is fixed and public anyway.
function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

if (!safeEqual(sent, computed)) {
  throw new Error(
    'HMAC verification failed — body was altered in transit, or the secret does not ' +
    'match N8N_WEBHOOK_SECRET in agent/.env'
  );
}

// Parse the verified body. Header Auth proved the caller knows the secret; the HMAC
// proved the bytes were not changed. Only now is it safe to act on the contents.
const body = JSON.parse(
  Buffer.from($('Webhook: agent-action').first().binary.data.data, 'base64').toString('utf8')
);

// IDEMPOTENCY.
// The agent reuses one run_id across every retry, so a response lost AFTER this workflow
// committed work arrives again with the same key. Without this check that is a second
// ticket, a second filing, a second notification.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

// Bounded to the most recent 500 keys so it cannot grow without limit.
const keys = Object.keys(store.seen);
if (keys.length > 500) {
  keys.sort((a, b) => store.seen[a] - store.seen[b]);
  keys.slice(0, keys.length - 500).forEach(k => delete store.seen[k]);
}

const duplicate = Boolean(store.seen[body.run_id]);
store.seen[body.run_id] = Date.now();

return [{
  json: {
    duplicate,
    run_id: body.run_id,
    action: body.action,
    payload: body.payload,
    evidence: body.evidence,
    approved_by: body.approved_by,
    schema_version: body.schema_version,
  },
}];
